export class IntakeError extends Error {
    code;
    constructor(code, message) { super(`${code}: ${message}`); this.name = 'IntakeError'; this.code = code; }
}
export function parseEml(text, attachments = []) { const split = text.split(/\r?\n\r?\n/); const head = split.shift() ?? ''; const body = split.join('\n\n').trim(); const h = (name) => { const m = new RegExp(`^${name}:\\s*(.+)$`, 'im').exec(head); return m?.[1]?.trim() ?? ''; }; const subject = h('Subject'), from = h('From'), date = h('Date'), mid = h('Message-ID') || `mid-${hash(text)}`; const thread = h('Thread-Id') || mid; if (!subject || !from)
    throw new IntakeError('E_LEGAL_EML_INVALID', 'EML needs Subject and From'); return { message_id: mid, thread_id: thread, subject, from, date, body, attachments }; }
export function hash(text) { let h = 5381; for (let i = 0; i < text.length; i++)
    h = ((h << 5) + h + text.charCodeAt(i)) | 0; return Math.abs(h).toString(36); }
export function classify(subject, body) { const t = `${subject}\n${body}`; if (/NDA|保密协议/i.test(t))
    return 'NDA'; if (/MSA|主协议|框架协议/i.test(t))
    return 'MSA'; if (/审查|审阅|review/i.test(t))
    return 'CONTRACT_REVIEW'; if (/诉讼|仲裁|争议/i.test(t))
    return 'DISPUTE'; if (/合规|GDPR|数据/i.test(t))
    return 'COMPLIANCE'; return 'OTHER'; }
